        emon.Testport.assertEq(emon.Port.cellsAt(res, 3), Plan.auId(Plan.auDecode()), "of frame 0, under the asset unit's id");
        emon.Testport.assertEq(emon.Port.cellsAt(res, 4), 3, "of the input");
