        emon.Testport.assertEq(emon.Port.cellsAt(res, 9), 1, "one asset");
        emon.Testport.assertEq(emon.Port.cellsAt(res, 10), 0, "the figure has it");
        emon.Testport.assertEq(emon.Port.cellsAt(res, 11), -1, "and no reason");
        emon.Testport.assertEq(emon.Port.cellsAt(res, 12), Model.aoCropped(), "cropped");
        emon.Testport.assertEq(emon.Port.cellsAt(res, 13), Model.afmPng(), "from a PNG input");
        emon.Testport.assertEq(emon.Port.cellsAt(res, 14), 101, "101 pixels across: floor(20000 * 306 / 61200) = 100 to ceil(40100 * 306 / 61200) = 201");
        emon.Testport.assertEq(emon.Port.cellsAt(res, 15), 101, "and down: 150 to 251");
        emon.Testport.assertEq(emon.Port.cellsAt(res, 16), 0, "no render dpi");
        emon.Testport.assertEq(emon.Port.cellsAt(res, 17), 0, "no flags");
        emon.Testport.assertEq(emon.Port.cellsAt(res, 18), 1, "the PNG is the pixels of the rectangle, byte for byte, with no resampling");
