    public static int afReuse(emon.Port.Cells res) {
        // Two figures whose renders are the same pixels are one asset with two uses; a third whose are not is asset 1.
        emon.Port.Cells nodes = emon.Port.newCells();
        emon.Port.Cells attrs = emon.Port.newCells();
        emon.Port.Cells regions = emon.Port.newCells();
        emon.Port.Cells text = emon.Port.newCells();
        emon.Port.Cells pages = emon.Port.newCells();
        emon.Port.Cells ledger = emon.Port.newCells();
        emon.Port.Cells layout = emon.Port.newCells();
        emon.Port.Cells assets = emon.Port.newCells();
        emon.Port.Cells uses = emon.Port.newCells();
        emon.Port.Cells cand = emon.Port.newCells();
        emon.Port.Cells ans = emon.Port.newCells();
        emon.Port.Cells rq = emon.Port.newCells();
        emon.Port.Cells box = emon.Port.newCells();
        emon.Port.Cells ws = emon.Port.newCells();
        emon.Port.Cells rows = emon.Port.newCells();
        emon.Port.Cells tmp = emon.Port.newCells();
        emon.Port.Cells rec = emon.Port.newCells();
        emon.Port.Buf cbytes = emon.Port.newBuf();
        emon.Port.Buf abytes = emon.Port.newBuf();
        emon.Port.Buf z = emon.Port.newBuf();
        emon.Port.BitmapSet bms = emon.Port.newBitmapSet();
        int a = 0;
        int b = 0;
        int d = 0;
        Model.modelInit(nodes, attrs, regions, text, pages, ledger, layout);
        Model.pageNew(pages, 1, 61200, 79200, 0, Model.pkVector());
        a = afNode(nodes, regions, 0, Model.nkFigure(), Model.fgUnknown(), 1, 10000, 10000, 20000, 20000);
        b = afNode(nodes, regions, 0, Model.nkFigure(), Model.fgUnknown(), 1, 30000, 10000, 40000, 20000);
        d = afNode(nodes, regions, 0, Model.nkFigure(), Model.fgUnknown(), 1, 10000, 30000, 21000, 41000);
        afBoxcells(box);
        // the three crops, 36 dpi: 100 x 100 px each or so; the first two the same bitmap, the third another size
        Plan.anRender(ans, Plan.auId(a), 105, 105, 3, 150);
        afFill(emon.Port.bmsPut(bms, Plan.auId(a), 105, 105, 3), 105, 105, 3);
        Plan.anRender(ans, Plan.auId(b), 105, 105, 3, 150);
        afFill(emon.Port.bmsPut(bms, Plan.auId(b), 105, 105, 3), 105, 105, 3);
        Plan.anRender(ans, Plan.auId(d), 110, 110, 3, 150);
        afFill(emon.Port.bmsPut(bms, Plan.auId(d), 110, 110, 3), 110, 110, 3);
        Asset.asRunFigures(nodes, attrs, regions, pages, cand, cbytes, assets, uses, abytes, 4194304, 33554432, 0, 150, 4194304, 3, 1234, 0, ans, rq, bms, ws, z, rows, tmp, rec, box);
        emon.Port.cellsDrop(res, 0);
        emon.Port.cellsPush(res, emon.Port.cellsLen(rq));
        emon.Port.cellsPush(res, Model.assetCount(assets));
        emon.Port.cellsPush(res, Model.nodeAttrIntOr(nodes, attrs, a, Model.fkAsset(), -1));
        emon.Port.cellsPush(res, Model.nodeAttrIntOr(nodes, attrs, b, Model.fkAsset(), -1));
        emon.Port.cellsPush(res, Model.nodeAttrIntOr(nodes, attrs, d, Model.fkAsset(), -1));
        emon.Port.cellsPush(res, Model.assetUseCount(assets, 0));
        return 0;
    }
